<script setup lang="ts">
import { computed, ref } from 'vue'; import type { MarketRow } from '../types.js';
const props = defineProps<{ rows: readonly MarketRow[] }>(); const venue = ref('All'); const search = ref('');
const venues = computed(() => ['All', ...new Set(props.rows.map((row) => row.venue))]);
const filtered = computed(() => props.rows.filter((row) => (venue.value === 'All' || row.venue === venue.value) && row.symbol.toLowerCase().includes(search.value.toLowerCase())));
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">Normalized market data</p><h2>Market Explorer</h2><p>Quotes, depth coverage and freshness across connected venues.</p></div></div><article class="panel filters"><el-input v-model="search" placeholder="Search symbol" clearable /><el-select v-model="venue"><el-option v-for="item in venues" :key="item" :label="item === 'All' ? 'All venues' : item" :value="item" /></el-select><span class="filter-result">{{ filtered.length }} markets</span></article><article class="panel table-panel"><el-table :data="filtered"><el-table-column prop="symbol" label="Symbol" width="125"><template #default="scope"><strong>{{ scope.row.symbol }}</strong></template></el-table-column><el-table-column prop="venue" label="Venue" /><el-table-column prop="type" label="Market Type" /><el-table-column label="Best Bid" align="right"><template #default="scope">{{ scope.row.bid.toLocaleString(undefined,{maximumFractionDigits:6}) }}</template></el-table-column><el-table-column label="Best Ask" align="right"><template #default="scope">{{ scope.row.ask.toLocaleString(undefined,{maximumFractionDigits:6}) }}</template></el-table-column><el-table-column label="Spread" align="right"><template #default="scope">{{ scope.row.spreadBps.toFixed(1) }} bps</template></el-table-column><el-table-column label="$25k Depth" align="right"><template #default="scope"><el-progress :percentage="scope.row.depth25k * 100" :show-text="false" :stroke-width="6" /></template></el-table-column><el-table-column label="Age" align="right"><template #default="scope">{{ scope.row.ageMs }} ms</template></el-table-column><el-table-column label="Status"><template #default="scope"><span :class="scope.row.status === 'healthy' ? 'status-good' : 'status-bad'"><i />{{ scope.row.status }}</span></template></el-table-column></el-table></article></section></template>
